import{_ as e,a as o,b as i,c as s}from"./chunks/sideview_2.Cqx9o4NU.js";import{_ as n,C as l,o as d,c as p,j as a,a as c,E as u,al as h}from"./chunks/framework.7vp1BMOE.js";const y=JSON.parse('{"title":"CORVON V5 Autopilot","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/corvon_v5.md","filePath":"en/flight_controller/corvon_v5.md"}'),m={name:"en/flight_controller/corvon_v5.md"};function g(f,t,b,v,P,S){const r=l("Badge");return d(),p("div",null,[t[0]||(t[0]=a("h1",{id:"corvon-v5-autopilot",tabindex:"-1"},[c("CORVON V5 Autopilot "),a("a",{class:"header-anchor",href:"#corvon-v5-autopilot","aria-label":'Permalink to "CORVON V5 Autopilot"'},"​")],-1)),u(r,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=h('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://corvon.tech" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The CORVON V5 is based on the Pixhawk FMUv5 design standard and runs PX4 on NuttX.</p><p><img src="'+e+'" alt="CORVON V5 side view 1"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><ul><li><p><strong>Main FMU Processor:</strong> STM32F765IIK</p><ul><li>32 Bit Arm® Cortex®-M7, 216MHz, 2MB memory, 512KB RAM</li></ul></li><li><p><strong>On-board sensors:</strong></p><ul><li>Accel/Gyro: ICM-20689</li><li>Accel/Gyro: ICM-20602</li><li>Accel/Gyro: BMI088</li><li>Magnetometer: IST8310</li><li>Barometer: MS5611</li></ul></li><li><p><strong>Interfaces:</strong></p><ul><li>8 PWM outputs</li><li>3 dedicated PWM/Capture inputs on FMU</li><li>Dedicated R/C input for CPPM</li><li>Dedicated R/C input for Spektrum / DSM and S.Bus</li><li>Analog / PWM RSSI input</li><li>4 general purpose serial ports</li><li>3 I2C ports</li><li>4 SPI buses</li><li>2 CAN Buses</li><li>Analog inputs for voltage / current of battery</li><li>2 additional analog inputs</li><li>Supports nARMED</li></ul></li><li><p><strong>Power System:</strong></p><ul><li>Power Brick Input: 4.75~5.5V</li><li>USB-C Power Input: 4.75~5.25V</li></ul></li><li><p><strong>Weight and Dimensions:</strong></p><ul><li>Weight: 42.1g</li><li>Dimensions: 61.2 x 40 x 15.9mm</li></ul></li><li><p><strong>Other Characteristics:</strong></p><ul><li>Operating temperature: -20 ~ 85°C (Measured value)</li></ul></li></ul><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><ul><li><a href="https://corvon.tech" target="_blank" rel="noreferrer">CORVON Store</a></li></ul><h2 id="connectors-and-interfaces" tabindex="-1">Connectors and Interfaces <a class="header-anchor" href="#connectors-and-interfaces" aria-label="Permalink to &quot;Connectors and Interfaces&quot;">​</a></h2><p><img src="'+o+'" alt="Connectors and Interfaces"></p><h2 id="pinouts" tabindex="-1">Pinouts <a class="header-anchor" href="#pinouts" aria-label="Permalink to &quot;Pinouts&quot;">​</a></h2><p>Download Corvon V5 pinouts from here: <a href="https://github.com/PX4/PX4-Autopilot/raw/main/docs/assets/flight_controller/corvon_v5/corvon_v5_pinout.xlsx" target="_blank" rel="noreferrer">corvon_v5_pinout.xlsx</a></p><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Device</th><th>Port</th><th style="text-align:center;">Flow Control</th></tr></thead><tbody><tr><td>USART1</td><td><code>/dev/ttyS0</code></td><td>GPS</td><td style="text-align:center;">-</td></tr><tr><td>USART2</td><td><code>/dev/ttyS1</code></td><td>TELEM1</td><td style="text-align:center;">Yes</td></tr><tr><td>USART3</td><td><code>/dev/ttyS2</code></td><td>TELEM2</td><td style="text-align:center;">Yes</td></tr><tr><td>UART4</td><td><code>/dev/ttyS3</code></td><td>TELEM4</td><td style="text-align:center;">-</td></tr><tr><td>USART6</td><td><code>/dev/ttyS4</code></td><td>RC</td><td style="text-align:center;">-</td></tr><tr><td>UART7</td><td><code>/dev/ttyS5</code></td><td>Debug Console</td><td style="text-align:center;">-</td></tr><tr><td>UART8</td><td><code>/dev/ttyS6</code></td><td>Reserved for optional onboard RTK module</td><td style="text-align:center;">-</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>UART8 is reserved for an optional onboard UM982 module footprint and is not intended for general external use.</p></div><h2 id="radio_control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio_control" aria-label="Permalink to &quot;Radio Control {#radio_control}&quot;">​</a></h2><p>A remote control (RC) radio system is required if you want to <em>manually</em> control your vehicle (PX4 does not require a radio system for autonomous flight modes). You will need to <a href="./../getting_started/rc_transmitter_receiver">select a compatible transmitter/receiver</a> and then <em>bind</em> them so that they communicate (read the instructions that come with your specific transmitter/receiver).</p><p>The ports and supported protocols are:</p><ul><li><code>DSM/SBUS/RSSI</code> (FMU): SBUS, DSM/DSMX, ST24, SUMD, CRSF, and GHST receivers</li><li><code>RC</code>: PPM</li></ul><p>For PPM and S.Bus receivers, a single signal wire carries all channels. If your receiver outputs individual PWM signals (one wire per channel) it must be connected via a <a href="./../getting_started/rc_transmitter_receiver">PPM encoder</a>.</p><h3 id="gps_compass" tabindex="-1">GPS &amp; Compass <a class="header-anchor" href="#gps_compass" aria-label="Permalink to &quot;GPS &amp; Compass {#gps_compass}&quot;">​</a></h3><p>PX4 supports GPS modules connected to the GPS port(s) listed below. The module should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible, with the direction marker pointing towards the front of the vehicle.</p><p>The GPS ports are:</p><ul><li><code>GPS&amp;SAFETY</code> (FMU): 10-pin JST GH (<a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a>) — GPS, compass (I2C), safety switch, buzzer, LED.</li></ul><p>The GPS module&#39;s integrated safety switch is enabled <em>by default</em> (when enabled, PX4 will not let you arm the vehicle). To disable the safety switch press and hold it for 1 second. You can press the safety switch again to enable safety and disarm the vehicle.</p><h2 id="pwm_outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm_outputs" aria-label="Permalink to &quot;PWM Outputs {#pwm_outputs}&quot;">​</a></h2><p>This flight controller supports up to 8 FMU PWM outputs (<code>MAIN</code>).</p><p><a href="./../peripherals/dshot">DShot</a> is not supported.</p><p>The 8 outputs are in 3 groups:</p><ul><li>Outputs 1-4 in group1 (Timer1)</li><li>Outputs 5-6 in group2 (Timer4)</li><li>Outputs 7-8 in group3 (Timer12)</li></ul><p>All outputs within the same group must use the same output protocol and rate.</p><h2 id="debug_port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug_port" aria-label="Permalink to &quot;Debug Port {#debug_port}&quot;">​</a></h2><p>The <a href="./../debug/system_console">PX4 System Console</a> and <a href="./../debug/swd_debug">SWD interface</a> operate on the <strong>FMU Debug</strong> port (<code>DSU7</code>).</p><p>The debug port (<code>DSU7</code>) has the following pinout:</p><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>GND</td><td>GND</td></tr><tr><td>2</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>3</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>4</td><td>DEBUG RX</td><td>+3.3V</td></tr><tr><td>5</td><td>DEBUG TX</td><td>+3.3V</td></tr><tr><td>6</td><td>5V+</td><td>+5V</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The 5V+ pin (6) provides 5V, but the CPU logic runs at 3.3V!</p><p>Some JTAG/SWD adapters (like SEGGER J-Link) may use the Vref voltage pin to set the logic level on the SWD data lines. Connecting 5V to the adapter&#39;s <code>Vtref</code> can damage the CPU. For a direct connection to a <em>Segger Jlink</em>, we recommend you use a 3.3V source to provide <code>Vtref</code> to the JTAG adapter (i.e. providing 3.3V and <em>NOT</em> 5V).</p></div><h2 id="voltage-ratings" tabindex="-1">Voltage Ratings <a class="header-anchor" href="#voltage-ratings" aria-label="Permalink to &quot;Voltage Ratings&quot;">​</a></h2><p>CORVON V5 must be powered from the <strong>POWER</strong> connector during flight, and may also be powered from <strong>USB</strong> for bench testing.</p><ul><li><strong>POWER input:</strong> 4.75~5.5V</li><li><strong>USB input:</strong> 4.75~5.25V</li></ul><p>The <strong>PM2</strong> connector <strong>cannot power</strong> the flight controller. On PX4, <strong>do not use</strong> this interface.</p><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><p>To build PX4 for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corvon_v5_default</span></span></code></pre></div><h2 id="installing-px4-firmware" tabindex="-1">Installing PX4 Firmware <a class="header-anchor" href="#installing-px4-firmware" aria-label="Permalink to &quot;Installing PX4 Firmware&quot;">​</a></h2><p>The firmware can be installed in any of the normal ways:</p><ul><li><p><strong>Build and upload the source</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corvon_v5_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><strong>Load the firmware using <em>QGroundControl</em>.</strong> You can use either pre-built firmware or your own custom firmware.</p></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If this target is not listed in <em>QGroundControl</em>, build and upload from source or load a custom firmware file (see <a href="./../config/firmware#installing-px4-main-beta-or-custom-firmware">Installing PX4 Main, Beta or Custom Firmware</a>).</p></div><h2 id="supported-platforms-airframes" tabindex="-1">Supported Platforms / Airframes <a class="header-anchor" href="#supported-platforms-airframes" aria-label="Permalink to &quot;Supported Platforms / Airframes&quot;">​</a></h2><p>Any multicopter / airplane / rover or boat that can be controlled with normal RC servos or Futaba S-Bus servos. The complete set of supported configurations can be seen in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p><img src="'+i+'" alt="CORVON V5 front view"><img src="'+e+'" alt="CORVON V5 side view 1"><img src="'+s+'" alt="CORVON V5 side view 2"></p><h2 id="further-information" tabindex="-1">Further Information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further Information&quot;">​</a></h2><ul><li><a href="https://corvon.tech" target="_blank" rel="noreferrer">Corvon Tech</a></li></ul>',53))])}const C=n(m,[["render",g]]);export{y as __pageData,C as default};
